export function ClearFilters({
  label = "{{label}}",
  count = {{count}},
  active = {{active}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 340 }}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 10 }}>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#24143010", border: `1.5px solid ${accent}`, borderRadius: 999, padding: "4px 6px 4px 10px", fontSize: 13 }}>
          Status: Open
          <button type="button" aria-label="Remove filter: Status — Open" style={{ border: "none", background: "transparent", cursor: "pointer", width: 16, height: 16, borderRadius: "50%", color: "#241430" }}>×</button>
        </span>
        <span style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#24143010", border: `1.5px solid ${accent}`, borderRadius: 999, padding: "4px 6px 4px 10px", fontSize: 13 }}>
          Owner: Me
          <button type="button" aria-label="Remove filter: Owner — Me" style={{ border: "none", background: "transparent", cursor: "pointer", width: 16, height: 16, borderRadius: "50%", color: "#241430" }}>×</button>
        </span>
      </div>
      <p role="status" style={{ margin: "0 0 10px", fontSize: 13, color: "#24143099" }}>
        {active ? `${count} filters applied` : "No filters applied"}
      </p>
      <button type="button" disabled={!active} style={{
        border: `1.5px solid ${accent}`, background: "#FAF7F2", color: "#241430", padding: "8px 14px",
        borderRadius: 6, cursor: active ? "pointer" : "not-allowed", opacity: active ? 1 : 0.5,
      }}>{label}</button>
    </div>
  );
}
